sp_widget.client_script:
api.controller = function($location) {

    var c = this;


    /* =====================================================
       VARIABLES
    ====================================================== */

    c.loading = false;

    c.searching = false;

    c.claimFound = false;

    c.showSearch = false;

    c.claimNumber = "";

    c.searchError = "";

    c.claim = {};



    /* =====================================================
       LOAD CLAIM FROM URL
    ====================================================== */

    c.loadClaimFromURL = function() {

        var params =
            $location.search();

        var sysId =
            params.sys_id || "";


        if (!sysId) {

            c.loading = false;

            c.claimFound = false;

            c.showSearch = true;

            return;
        }


        c.loading = true;

        c.showSearch = false;

        c.searchError = "";


        c.server.get({

            action:
                "get_claim",

            sys_id:
                sysId

        }).then(function(response) {

            c.loading = false;


            if (
                response.data.success === true &&
                response.data.claimFound === true
            ) {

                c.claimFound = true;

                c.claim =
                    response.data.claim;

            } else {

                c.claimFound = false;

                c.showSearch = true;

                c.searchError =
                    response.data.message ||
                    "Claim was not found.";

            }

        }, function() {

            c.loading = false;

            c.claimFound = false;

            c.showSearch = true;

            c.searchError =
                "Unable to load claim.";

        });

    };



    /* =====================================================
       SEARCH CLAIM NUMBER
    ====================================================== */

    c.searchClaim = function() {

        c.searchError = "";

        c.claimFound = false;


        var number =
            String(
                c.claimNumber || ""
            ).trim();


        if (!number) {

            c.searchError =
                "Please enter a claim number.";

            return;
        }


        c.searching = true;

        c.showSearch = true;


        c.server.get({

            action:
                "get_claim",

            claim_number:
                number

        }).then(function(response) {

            c.searching = false;


            if (
                response.data.success === true &&
                response.data.claimFound === true
            ) {

                c.claim =
                    response.data.claim;

                c.claimFound = true;

                c.showSearch = false;


                /*
                 * Add sys_id to URL.
                 * This allows View Claim and
                 * direct tracking to use the
                 * same page.
                 */

                $location.search({

                    id:
                        "track_claim",

                    sys_id:
                        c.claim.sys_id

                });

            } else {

                c.claimFound = false;

                c.showSearch = true;

                c.searchError =
                    response.data.message ||
                    "Claim not found.";

            }

        }, function() {

            c.searching = false;

            c.searchError =
                "Unable to search for claim.";

        });

    };



    /* =====================================================
       ENTER KEY SEARCH
    ====================================================== */

    c.handleKeyPress = function(event) {

        if (
            event.keyCode === 13 ||
            event.which === 13
        ) {

            c.searchClaim();

        }

    };



    /* =====================================================
       GO TO MY CLAIMS
    ====================================================== */

    c.goToMyClaims = function() {

        $location.search({

            id:
                "my_claims"

        });

    };



    /* =====================================================
       SHOW SEARCH
    ====================================================== */

    c.showClaimSearch = function() {

        c.claimFound = false;

        c.showSearch = true;

        c.searchError = "";

        c.claimNumber = "";

    };



    /* =====================================================
       REFRESH
    ====================================================== */

    c.refreshClaim = function() {

        var params =
            $location.search();

        var sysId =
            params.sys_id || "";


        if (!sysId) {

            c.loadClaimFromURL();

            return;
        }


        c.loading = true;


        c.server.get({

            action:
                "get_claim",

            sys_id:
                sysId

        }).then(function(response) {

            c.loading = false;


            if (
                response.data.success === true
            ) {

                c.claim =
                    response.data.claim;

                c.claimFound = true;

            }

        });

    };



    /* =====================================================
       STATUS CLASS
    ====================================================== */

    c.getStatusClass = function(status) {

        if (!status) {

            return "status-pending";

        }


        var value =
            String(status)
                .toLowerCase()
                .replace(/\s+/g, "-");


        if (
            value.indexOf("approved") >= 0
        ) {

            return "status-approved";

        }


        if (
            value.indexOf("rejected") >= 0
        ) {

            return "status-rejected";

        }


        if (
            value.indexOf("review") >= 0
        ) {

            return "status-review";

        }


        if (
            value.indexOf("processing") >= 0
        ) {

            return "status-processing";

        }


        return "status-pending";

    };



    /* =====================================================
       PROCESS STEP
    ====================================================== */

    c.getStepClass = function(step) {

        /*
         * Keep first step completed.
         * Later we can connect this to
         * actual claim status values.
         */

        if (step == 1) {

            return "completed";

        }


        return "";

    };



    /* =====================================================
       INITIAL LOAD
    ====================================================== */

    c.loadClaimFromURL();

};

sp_widget.css:
/* =========================================================
   TRACK CLAIM - PROFESSIONAL UI
========================================================= */

.track-claim-container {

    width: 100%;
    max-width: 1100px;

    margin: 0 auto;

    padding: 38px 28px 60px;

    box-sizing: border-box;

    font-family:
        "Segoe UI",
        Arial,
        sans-serif;

    color: #1e293b;

}


/* =========================================================
   HEADER
========================================================= */

.track-header {

    display: flex;

    justify-content: space-between;

    align-items: center;

    gap: 20px;

    margin-bottom: 25px;

    padding-bottom: 20px;

    border-bottom: 1px solid #dbe5ef;

}


.track-badge {

    display: inline-block;

    margin-bottom: 7px;

    padding: 5px 10px;

    border-radius: 20px;

    background: #e0f2fe;

    color: #0369a1;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: .8px;

}


.track-header h1 {

    margin: 0;

    color: #073b66;

    font-size: 29px;

    font-weight: 750;

}


.track-header p {

    margin: 6px 0 0;

    color: #64748b;

    font-size: 12px;

}


.back-claims-btn {

    padding: 10px 18px;

    border: 1px solid #0284c7;

    border-radius: 8px;

    background: #ffffff;

    color: #0369a1;

    font-size: 11px;

    font-weight: 700;

    cursor: pointer;

}


.back-claims-btn:hover {

    background: #0369a1;

    color: #ffffff;

}


/* =========================================================
   SEARCH CARD
========================================================= */

.claim-search-card {

    display: flex;

    gap: 20px;

    align-items: flex-start;

    margin-bottom: 25px;

    padding: 25px;

    border: 1px solid #bfdbfe;

    border-radius: 15px;

    background:
        linear-gradient(
            135deg,
            #eff6ff,
            #f0f9ff
        );

    box-shadow:
        0 8px 22px rgba(30, 64, 175, .08);

}


.search-icon {

    width: 48px;

    height: 48px;

    min-width: 48px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 12px;

    background: #ffffff;

    font-size: 20px;

}


.search-content {

    width: 100%;

}


.search-content h2 {

    margin: 0;

    color: #0f3b5f;

    font-size: 19px;

}


.search-content p {

    margin: 6px 0 16px;

    color: #64748b;

    font-size: 12px;

}


.search-row {

    display: flex;

    gap: 10px;

}


.claim-search-input {

    flex: 1;

    height: 42px;

    padding: 0 14px;

    border: 1px solid #cbd5e1;

    border-radius: 8px;

    outline: none;

    background: #ffffff;

    color: #1e293b;

    font-size: 13px;

}


.claim-search-input:focus {

    border-color: #0284c7;

    box-shadow:
        0 0 0 3px rgba(2,132,199,.12);

}


.search-claim-btn {

    height: 42px;

    padding: 0 20px;

    border: none;

    border-radius: 8px;

    background:
        linear-gradient(
            135deg,
            #2563eb,
            #0284c7
        );

    color: #ffffff;

    font-size: 12px;

    font-weight: 700;

    cursor: pointer;

}


.search-claim-btn:hover {

    filter: brightness(1.08);

}


.search-error {

    margin-top: 10px;

    padding: 10px 12px;

    border-radius: 7px;

    background: #fff1f2;

    color: #be123c;

    font-size: 11px;

}


/* =========================================================
   CLAIM NUMBER
========================================================= */

.claim-number-card {

    display: flex;

    justify-content: space-between;

    align-items: center;

    padding: 22px;

    margin-bottom: 16px;

    border: 1px solid #dbe5ef;

    border-radius: 12px;

    background: #ffffff;

    box-shadow:
        0 5px 18px rgba(15,23,42,.06);

}


.claim-number {

    margin-top: 5px;

    color: #0569a6;

    font-size: 21px;

    font-weight: 800;

}


/* =========================================================
   LABEL
========================================================= */

.field-label {

    display: block;

    margin-bottom: 5px;

    color: #64748b;

    font-size: 9px;

    font-weight: 600;

}


/* =========================================================
   STATUS
========================================================= */

.status-badge {

    display: inline-flex;

    align-items: center;

    gap: 6px;

    padding: 7px 13px;

    border-radius: 20px;

    font-size: 10px;

    font-weight: 700;

}


.status-dot {

    width: 6px;

    height: 6px;

    border-radius: 50%;

    background: currentColor;

}


.status-pending {

    background: #fef3c7;

    color: #a16207;

}


.status-approved {

    background: #dcfce7;

    color: #15803d;

}


.status-rejected {

    background: #fee2e2;

    color: #b91c1c;

}


.status-review {

    background: #dbeafe;

    color: #1d4ed8;

}


.status-processing {

    background: #ede9fe;

    color: #6d28d9;

}


/* =========================================================
   INFORMATION CARD
========================================================= */

.information-card {

    margin-bottom: 16px;

    padding: 22px;

    border: 1px solid #dbe5ef;

    border-radius: 12px;

    background: #ffffff;

    box-shadow:
        0 5px 18px rgba(15,23,42,.055);

}


.card-title {

    display: flex;

    align-items: center;

    gap: 9px;

    margin-bottom: 20px;

    padding-bottom: 13px;

    border-bottom: 1px solid #edf2f7;

}


.title-icon {

    font-size: 16px;

}


.card-title h2 {

    margin: 0;

    color: #0f3b5f;

    font-size: 16px;

}


/* =========================================================
   INFORMATION GRID
========================================================= */

.information-grid {

    display: grid;

    grid-template-columns:
        1fr 1fr;

    column-gap: 70px;

    row-gap: 20px;

}


.information-item strong {

    display: block;

    color: #334155;

    font-size: 12px;

    font-weight: 650;

}


.information-item .amount {

    color: #047857;

}


/* =========================================================
   DESCRIPTION
========================================================= */

.description-box {

    min-height: 60px;

    padding: 15px;

    border-radius: 8px;

    background: #f8fafc;

    color: #475569;

    font-size: 12px;

    line-height: 1.6;

}


/* =========================================================
   TIMELINE
========================================================= */

.process-timeline {

    position: relative;

    padding-left: 10px;

}


.process-timeline::before {

    content: "";

    position: absolute;

    left: 14px;

    top: 13px;

    bottom: 13px;

    width: 2px;

    background: #dbeafe;

}


.process-step {

    position: relative;

    display: flex;

    gap: 14px;

    min-height: 70px;

}


.step-number {

    position: relative;

    z-index: 2;

    width: 29px;

    height: 29px;

    min-width: 29px;

    display: flex;

    align-items: center;

    justify-content: center;

    border: 2px solid #3b82f6;

    border-radius: 50%;

    background: #ffffff;

    color: #2563eb;

    font-size: 10px;

    font-weight: 800;

}


.process-step.completed .step-number {

    background: #2563eb;

    color: #ffffff;

}


.process-step.current .step-number {

    background: #dbeafe;

    color: #1d4ed8;

    box-shadow:
        0 0 0 5px #eff6ff;

}


.step-content {

    padding-top: 2px;

}


.step-content h3 {

    margin: 0 0 4px;

    color: #0f3b5f;

    font-size: 12px;

}


.step-content p {

    margin: 0;

    color: #64748b;

    font-size: 10px;

}


/* =========================================================
   REFRESH
========================================================= */

.refresh-area {

    display: flex;

    justify-content: center;

    margin-top: 20px;

}


.refresh-btn {

    padding: 10px 18px;

    border: 1px solid #0284c7;

    border-radius: 8px;

    background: #ffffff;

    color: #0369a1;

    font-size: 11px;

    font-weight: 700;

    cursor: pointer;

}


.refresh-btn:hover {

    background: #0369a1;

    color: #ffffff;

}


/* =========================================================
   LOADING
========================================================= */

.loading-card {

    min-height: 250px;

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

}


.loading-spinner {

    width: 38px;

    height: 38px;

    border: 4px solid #dbeafe;

    border-top-color: #0284c7;

    border-radius: 50%;

    animation:
        trackSpin .8s linear infinite;

}


@keyframes trackSpin {

    to {
        transform: rotate(360deg);
    }

}


.loading-card p {

    margin-top: 12px;

    color: #64748b;

    font-size: 12px;

}


/* =========================================================
   NOT FOUND
========================================================= */

.not-found-card {

    padding: 55px 30px;

    text-align: center;

    border: 1px solid #dbe5ef;

    border-radius: 15px;

    background: #ffffff;

    box-shadow:
        0 8px 25px rgba(15,23,42,.07);

}


.not-found-icon {

    font-size: 35px;

    margin-bottom: 10px;

}


.not-found-card h2 {

    margin: 0 0 7px;

    color: #0f3b5f;

    font-size: 22px;

}


.not-found-card p {

    margin: 0 0 20px;

    color: #64748b;

    font-size: 12px;

}


.back-claims-large {

    padding: 10px 18px;

    border: 1px solid #0284c7;

    border-radius: 8px;

    background: #ffffff;

    color: #0369a1;

    font-size: 11px;

    font-weight: 700;

    cursor: pointer;

}


.back-claims-large:hover {

    background: #0369a1;

    color: #ffffff;

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 700px) {

    .track-claim-container {

        padding: 25px 15px 45px;

    }


    .track-header {

        flex-direction: column;

        align-items: flex-start;

    }


    .back-claims-btn {

        width: 100%;

    }


    .claim-search-card {

        flex-direction: column;

    }


    .search-row {

        flex-direction: column;

    }


    .search-claim-btn {

        width: 100%;

    }


    .information-grid {

        grid-template-columns: 1fr;

        row-gap: 16px;

    }


    .claim-number-card {

        align-items: flex-start;

        gap: 15px;

        flex-direction: column;

    }

}

sp_widget.script:
(function() {

    data.success = false;
    data.claimFound = false;
    data.claim = {};
    data.message = "";

    if (!input) {
        return;
    }


    /* =====================================================
       GET CLAIM
    ====================================================== */

    if (input.action == "get_claim") {

        var sysId =
            String(input.sys_id || "").trim();

        var claimNumber =
            String(input.claim_number || "").trim();


        if (!sysId && !claimNumber) {

            data.message =
                "Please provide a claim number.";

            return;
        }


        var claim =
            new GlideRecord(
                "x_snc_insurance_0_claim"
            );


        /* Search by sys_id */

        if (sysId) {

            if (!claim.get(sysId)) {

                data.message =
                    "Claim was not found.";

                return;
            }

        }

        /* Search by Claim Number */

        else {

            claim.addQuery(
                "claim_number",
                claimNumber
            );

            claim.setLimit(1);

            claim.query();


            if (!claim.next()) {

                data.message =
                    "No claim found with claim number: " +
                    claimNumber;

                return;
            }

        }


        /* =================================================
           GET DISPLAY VALUES
        ================================================== */

        data.claim = {

            sys_id:
                claim.getUniqueValue(),

            claim_number:
                claim.getValue(
                    "claim_number"
                ) || "",

            claim_type:
                claim.getDisplayValue(
                    "claim_type"
                ) || "",

            incident_date:
                claim.getDisplayValue(
                    "incident_date"
                ) || "",

            claim_amount:
                claim.getDisplayValue(
                    "claim_amount"
                ) || "₹0",

            policy_number:
                claim.getDisplayValue(
                    "policy_number"
                ) || "",

            policy_match:
                claim.getDisplayValue(
                    "policy_match"
                ) || "Pending",

            fraud_risk:
                claim.getDisplayValue(
                    "fraud_risk"
                ) || "Pending",

            fraud_score:
                claim.getValue(
                    "fraud_score"
                ) || "0",

            recommended_payout:
                claim.getDisplayValue(
                    "recommended_payout"
                ) || "₹0",

            final_payout:
                claim.getDisplayValue(
                    "final_payout"
                ) || "₹0",

            adjuster_decision:
                claim.getDisplayValue(
                    "adjuster_decision"
                ) || "Pending",

            status:
                claim.getDisplayValue(
                    "status"
                ) || "Pending",

            description:
                claim.getValue(
                    "description"
                ) || ""

        };


        data.success = true;
        data.claimFound = true;

        return;
    }

})();
